import json, importlib.util
print('matplotlib', importlib.util.find_spec('matplotlib') is not None)
print('numpy', importlib.util.find_spec('numpy') is not None)
src=json.load(open('/app/benchmark/source_data.json'))
sp={d['country']:d for d in src['education_spending']['data']}
pi={d['country']:d for d in src['pisa_scores']['data']}
te={d['country']:d for d in src['tertiary_enrollment']['data']}
yu={d['country']:d for d in src['youth_unemployment']['data']}
rows=[]
for c in sp:
    rows.append({**sp[c], **pi[c], **te[c], **yu[c]})
for r in rows:
    print(r)
def median(vals):
    vals=sorted(vals); n=len(vals); return (vals[n//2-1]+vals[n//2])/2 if n%2==0 else vals[n//2]
print('medians', median([r['edu_spending_pct_gdp'] for r in rows]), median([r['pisa_avg'] for r in rows]), median([r['youth_unemp_rate'] for r in rows]), median([r['enrollment_rate'] for r in rows]))
print('high spenders')
for r in sorted([r for r in rows if r['edu_spending_pct_gdp']>=6.0], key=lambda x:-x['pisa_avg']): print(r)
